type DeepReadonly<T> =
  T extends (...args: never[]) => unknown ? T                 // keep functions callable
  : T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> }  // arrays and tuples stay arrays
  : T;                                                        // primitives unchanged

function deepFreeze<T>(value: T, seen = new WeakSet<object>()): DeepReadonly<T> {
  if (typeof value === 'object' && value !== null && !seen.has(value)) {
    seen.add(value);
    for (const key of Reflect.ownKeys(value)) {
      deepFreeze((value as Record<PropertyKey, unknown>)[key], seen);
    }
    Object.freeze(value);
  }
  return value as DeepReadonly<T>;
}

const settings = deepFreeze({ theme: 'dark', editor: { tabSize: 2, rulers: [80, 120] } });
// settings.editor.tabSize = 4;      // error: tabSize is read-only
// settings.editor.rulers.push(100); // error: push does not exist on readonly number[]
console.log(Object.isFrozen(settings.editor.rulers));  // true: runtime agrees with the type

