type Without<T, K extends keyof T> = {
  [P in keyof T as P extends K ? never : P]: T[P];
};

function omit<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Without<T, K> {
  const drop = new Set<PropertyKey>(keys);
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (!drop.has(key)) out[key] = value;
  }
  return out as Without<T, K>;
}

type Path<T> = T extends readonly unknown[]
  ? never
  : T extends object
    ? { [K in keyof T & string]: K | `${K}.${Path<T[K]>}` }[keyof T & string]
    : never;

type PathValue<T, P extends string> = P extends `${infer Head}.${infer Rest}`
  ? Head extends keyof T
    ? PathValue<T[Head], Rest>
    : never
  : P extends keyof T
    ? T[P]
    : never;

function getPath<T extends object, P extends Path<T>>(obj: T, path: P): PathValue<T, P> {
  let current: unknown = obj;
  for (const key of path.split('.')) {
    if (typeof current !== 'object' || current === null) break;
    current = (current as Record<string, unknown>)[key];
  }
  return current as PathValue<T, P>;
}

